// LoopRaider 打磨版音效 / 背景音樂。全域物件 window.Sound, 不用 ES module(file:// 下會被擋)。
// 事件表、呼叫時機與 opts 見同資料夾的 sound.md; 素材來源見 credits.md。
// 音效以 mp3 base64 內嵌(頁面載入時就先解碼, 不經 fetch); 解碼失敗或沒有 Web Audio 時退回 <audio> 播放池。
// 背景音樂用 <audio> 播 audio/assets/music_*.mp3(路徑相對於 index.html)。
(function () {
  'use strict';

  // ---- 事件設定 ----------------------------------------------------------
  // 音量已在素材裡依 sound.md 的相對響度做好, 這裡是執行時的倍率(1 = 原檔)。
  var SFX_VOL = {};
  // 同名事件的最短間隔(秒): 規格要求的限頻, RD 漏做也不會疊成一團(polish 第 6 輪: tut_type 0.07 → 0.09)
  var MIN_GAP = { hit: 0.05, coin_land: 0.06, drop_collect: 0.08, hit_block: 0.05, ui_move: 0.03, arrow: 0.05, rock_drop: 0.05, boss_rock: 0.08, pickup: 0.03, slash: 0.05, tut_type: 0.09, tut_pop: 0.05, tut_go: 0.2 };
  // 同名事件「新的一聲起時, 前一聲在幾秒內淡出」: 快速連按時不疊加、不爆音(淡出而非硬切, 無喀聲)
  var CHOKE = { slash: 0.015 };
  // 每次播放隨機微調音高(±比例), 連續觸發時不會像機關槍
  var JITTER = { hit: 0.06, coin_land: 0.08, drop_collect: 0.08, arrow: 0.05, slash: 0.05, pickup: 0.05, ui_move: 0.04, jump: 0.04, land: 0.04, rock_drop: 0.06, boss_rock: 0.05, hit_block: 0.05, bee_shot: 0.05, tut_type: 0.1 };
  // 連續觸發時一聲比一聲高(半音數 × 第幾聲, 最多 max 階): 總結板四張卡依序排上的節奏感; gap 秒內算同一串
  var STEP = { summary_card: { gap: 0.8, semi: 2, max: 3 } };
  var stepN = {};
  // 同一瞬間的讓位: 播左邊的事件時, 前後 0.06 秒內的右邊事件不出聲(已響的立刻收掉)
  var SUPPRESS = {
    monster_down: ['hit'],
    brood_down: ['hit', 'monster_down'],
    boss_down: ['hit', 'monster_down', 'hit_block', 'boss_phase'],
    boss_phase: ['hit'],
    shield_break: ['hit_block'],
    level_fail: ['player_hurt'],
    player_death: ['player_hurt'],
    tutorial_done: ['ui_back']
  };
  var SUPPRESS_WIN = 0.06;
  // 關卡內的動作音: 這些出聲代表遊戲沒在暫停, 用來自動解除「暫停壓低音樂」(防 RD 漏呼叫繼續)
  var GAMEPLAY = { jump: 1, land: 1, slash: 1, dash: 1, arrow: 1, bomb_throw: 1, hit: 1, player_hurt: 1, explosion: 1, bee_shot: 1, hawk_dive: 1, windup: 1 };
  var MUSIC = {
    title: { file: 'music_title.mp3', vol: 0.45 },
    map: { file: 'music_map.mp3', vol: 0.58 },
    forest: { file: 'music_forest.mp3', vol: 0.45 },
    cliff: { file: 'music_cliff.mp3', vol: 0.55 },
    mine: { file: 'music_mine.mp3', vol: 0.55 },
    boss: { file: 'music_boss.mp3', vol: 0.47 },
    ending: { file: 'music_ending.mp3', vol: 0.75 }
  };
  var BASE = 'audio/assets/';
  var FADE = 0.8;          // 換曲淡出 / 淡入秒數
  var DUCK = 0.5;          // 暫停時音樂音量倍率

  var SFX_B64 = {
    ui_move: "",
    ui_confirm: "",
    ui_back: "",
    ui_deny: "",
    title_start: "",
    unlock_level: "",
    repair: "",
    fog_clear: "",
    buy_item: "",
    equip: "",
    upgrade: "",
    unlock_class: "",
    coin_land: "",
    jump: "",
    land: "",
    slash: "",
    dash: "",
    arrow: "",
    stealth_on: "",
    stealth_off: "",
    bomb_throw: "",
    explosion: "",
    shockwave: "",
    hit: "",
    hit_block: "",
    shield_break: "",
    drop_collect: "",
    pickup: "",
    chest_open: "",
    item_get: "",
    monster_down: "",
    chain: "",
    brood_down: "",
    windup: "",
    bee_shot: "",
    hawk_dive: "",
    rock_drop: "",
    beetle_fuse: "",
    player_hurt: "",
    skill_ready: "",
    goal_reach: "",
    level_clear: "",
    iris_close: "",
    player_death: "",
    shatter: "",
    level_fail: "",
    tutorial_done: "",
    boss_slam: "",
    boss_beam_charge: "",
    boss_beam: "",
    boss_rock: "",
    boss_weak: "",
    boss_phase: "",
    boss_down: "",
    pause: "",
    tut_pop: "",
    tut_type: "",
    tut_go: "",
    tut_next: "",
    tut_panel: "",
    tut_dock: "",
    tut_spot: "",
    respawn: "",
    respawn_land: "",
    summary_open: "",
    summary_card: ""
  };

  // ---- 狀態 --------------------------------------------------------------
  var inited = false, muted = false;
  var ctx = null, master = null;
  var buffers = {}, offsets = {};
  var pools = {};
  var lastPlay = {};        // name -> performance 秒
  var live = {};            // name -> [{src, t}]
  var paused = false, pausedAt = -1;
  var music = { cur: null, el: null, fading: [], want: null };
  var els = {};

  function now() { return (typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now()) / 1000; }
  function has(o, k) { return Object.prototype.hasOwnProperty.call(o, k); }

  // ---- 頁面載入時先解碼(不需要使用者操作) --------------------------------
  function b64ToBuf(s) {
    var bin = atob(s), n = bin.length, u = new Uint8Array(n);
    for (var i = 0; i < n; i++) u[i] = bin.charCodeAt(i);
    return u.buffer;
  }
  function findStart(buf) {
    // mp3 開頭有編碼器延遲與 20ms 靜音: 從第一個 |樣本| > 0.002 前 3ms 起播
    var d = buf.getChannelData(0), n = d.length, i = 0;
    while (i < n && Math.abs(d[i]) < 0.002) i++;
    return Math.max(0, i / buf.sampleRate - 0.003);
  }
  function predecode() {
    var OAC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    if (!OAC) return;
    var off;
    try { off = new OAC(1, 1, 44100); } catch (e) { return; }
    Object.keys(SFX_B64).forEach(function (name) {
      try {
        var done = function (b) { buffers[name] = b; offsets[name] = findStart(b); };
        var p = off.decodeAudioData(b64ToBuf(SFX_B64[name]), done, function () {});
        if (p && p.catch) p.catch(function () {});
      } catch (e) {}
    });
  }
  try { predecode(); } catch (e) {}

  // ---- 退回: <audio> 播放池(每事件 4 個複本輪流) -------------------------
  function poolPlay(name, vol, rate) {
    if (typeof Audio === 'undefined') return;
    var p = pools[name];
    if (!p) { p = pools[name] = { i: 0, a: [] }; for (var k = 0; k < 4; k++) { var a = new Audio(BASE + 'sfx_' + name + '.mp3'); a.preload = 'auto'; p.a.push(a); } }
    var el = p.a[p.i]; p.i = (p.i + 1) % p.a.length;
    try {
      el.volume = Math.max(0, Math.min(1, vol));
      el.playbackRate = rate;
      el.currentTime = 0.03;
      var r = el.play(); if (r && r.catch) r.catch(function () {});
    } catch (e) {}
  }

  // ---- 音樂 --------------------------------------------------------------
  function musicEl(name) {
    if (!els[name]) {
      var a = new Audio(BASE + MUSIC[name].file);
      a.loop = true; a.preload = 'auto'; a.volume = 0;
      a._fade = 0; a._target = 0;
      els[name] = a;
    }
    return els[name];
  }
  function applyMusicVol() {
    Object.keys(els).forEach(function (k) {
      var a = els[k];
      var v = MUSIC[k].vol * a._fade * (paused ? DUCK : 1);
      try { a.volume = Math.max(0, Math.min(1, v)); a.muted = muted; } catch (e) {}
    });
  }
  var fadeTimer = null;
  function tickFade() {
    var step = 0.05 / FADE, busy = false;
    Object.keys(els).forEach(function (k) {
      var a = els[k];
      if (a._fade < a._target) { a._fade = Math.min(a._target, a._fade + step); busy = true; }
      else if (a._fade > a._target) { a._fade = Math.max(a._target, a._fade - step); busy = true; }
      if (a._target <= 0 && a._fade <= 0 && !a.paused) { try { a.pause(); } catch (e) {} }
    });
    applyMusicVol();
    if (!busy && fadeTimer) { clearInterval(fadeTimer); fadeTimer = null; }
  }
  function startFade() { if (!fadeTimer && typeof setInterval !== 'undefined') fadeTimer = setInterval(tickFade, 50); }
  function startMusic(name) {
    var a = musicEl(name);
    a._target = 1;
    if (a.paused) {
      try { a.currentTime = 0; } catch (e) {}
      try { var r = a.play(); if (r && r.catch) r.catch(function () {}); } catch (e) {}
    }
    applyMusicVol(); startFade();
  }
  function setPaused(on) {
    paused = !!on; pausedAt = on ? now() : -1;
    applyMusicVol();
  }

  // ---- 公開介面 ----------------------------------------------------------
  var Sound = {
    init: function () {
      if (inited) { if (ctx && ctx.state === 'suspended' && ctx.resume) { try { ctx.resume(); } catch (e) {} } return; }
      inited = true;
      try {
        var AC = window.AudioContext || window.webkitAudioContext;
        if (AC) {
          ctx = new AC();
          master = ctx.createGain();
          master.gain.value = muted ? 0 : 1;
          master.connect(ctx.destination);
          if (ctx.state === 'suspended' && ctx.resume) ctx.resume();
        }
      } catch (e) { ctx = null; }
      if (music.want) { var w = music.want; music.want = null; music.cur = null; Sound.playMusic(w); }
    },

    play: function (name, opts) {
      try {
        if (!has(SFX_B64, name)) return;
        opts = opts || {};
        // 暫停壓低: 放在最前面, 不受未 init / 靜音 / 限頻影響
        if (name === 'pause') setPaused(has(opts, 'on') ? !!opts.on : !paused);
        else if (paused && GAMEPLAY[name] && now() - pausedAt > 0.15) setPaused(false);
        if (!inited || muted) return;
        var t = now();
        if (MIN_GAP[name] && lastPlay[name] !== undefined && t - lastPlay[name] < MIN_GAP[name]) return;
        // 被更高優先的事件讓位
        for (var big in SUPPRESS) {
          if (SUPPRESS[big].indexOf(name) >= 0 && lastPlay[big] !== undefined && t - lastPlay[big] < SUPPRESS_WIN) return;
        }
        var lastPrev = lastPlay[name];
        lastPlay[name] = t;
        if (SUPPRESS[name]) SUPPRESS[name].forEach(function (s) { stopRecent(s, t); });

        var vol = (has(SFX_VOL, name) ? SFX_VOL[name] : 1) * (typeof opts.volume === 'number' ? Math.max(0, Math.min(1, opts.volume)) : 1);
        var rate = 1;
        if (name === 'chain') { var n = Math.max(2, Math.min(10, opts.n | 0 || 2)); rate = Math.pow(2, (n - 2) * 2 / 12); }
        if (STEP[name]) {
          var sp = STEP[name], prev = lastPrev;
          stepN[name] = (prev !== undefined && t - prev < sp.gap) ? Math.min(sp.max, (stepN[name] || 0) + 1) : 0;
          rate *= Math.pow(2, stepN[name] * sp.semi / 12);
        }
        if (JITTER[name]) rate *= 1 + (Math.random() * 2 - 1) * JITTER[name];

        var buf = buffers[name];
        if (ctx && buf) {
          if (ctx.state === 'suspended' && ctx.resume) { try { ctx.resume(); } catch (e) {} }
          var src = ctx.createBufferSource();
          src.buffer = buf;
          src.playbackRate.value = rate;
          var g = ctx.createGain();
          g.gain.value = vol;
          src.connect(g); g.connect(master);
          src.start(0, offsets[name] || 0);
          var list = live[name] || (live[name] = []);
          if (CHOKE[name]) {
            list.forEach(function (o) {
              try {
                var ct = ctx.currentTime, gg = o.g.gain;
                gg.cancelScheduledValues(ct);
                gg.setValueAtTime(gg.value, ct);
                gg.linearRampToValueAtTime(0, ct + CHOKE[name]);
                o.src.stop(ct + CHOKE[name] + 0.01);
              } catch (e) {}
            });
            list.length = 0;
          }
          var rec = { src: src, t: t, g: g };
          list.push(rec);
          if (list.length > 6) list.shift();
          src.onended = function () { var l = live[name] || [], i = l.indexOf(rec); if (i >= 0) l.splice(i, 1); };
        } else {
          poolPlay(name, vol, rate);
        }
      } catch (e) {}
    },

    // 額外(非契約必要): 立即收掉某事件正在響的聲音, 例如預備中的怪被擊倒時收掉 windup / beetle_fuse
    stop: function (name) {
      try {
        var list = live[name]; if (!list) return;
        list.forEach(function (o) { try { o.src.stop(); } catch (e) {} });
        live[name] = [];
      } catch (e) {}
    },

    playMusic: function (name) {
      try {
        if (!has(MUSIC, name)) return;
        if (!inited) { music.want = name; return; }
        if (music.cur === name) { startMusic(name); return; }
        // 換曲: 清掉暫停壓低(防暫停中直接離開關卡), 但保留 0.15 秒內剛設的
        if (paused && now() - pausedAt > 0.15) paused = false;
        Object.keys(els).forEach(function (k) { if (k !== name) els[k]._target = 0; });
        music.cur = name;
        startMusic(name);
      } catch (e) {}
    },

    stopMusic: function () {
      try {
        music.want = null; music.cur = null;
        Object.keys(els).forEach(function (k) { els[k]._target = 0; });
        startFade();
      } catch (e) {}
    },

    setMuted: function (b) {
      muted = !!b;
      try { if (master) master.gain.value = muted ? 0 : 1; } catch (e) {}
      if (muted) { for (var k in live) Sound.stop(k); }
      applyMusicVol();
    },

    isMuted: function () { return muted; }
  };

  window.Sound = Sound;
  function stopRecent(name, t) {
    var list = live[name]; if (!list) return;
    for (var i = list.length - 1; i >= 0; i--) {
      if (t - list[i].t < SUPPRESS_WIN) { try { list[i].src.stop(); } catch (e) {} list.splice(i, 1); }
    }
  }
})();
